pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, bytes32 hash) public {
        vm.assume(caller != address(0) && caller != address(c));

        // Fund the caller with enough ether
        vm.deal(caller, 2 ether);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Call lockInGuess through the caller
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", hash));

        // The rule: if caller hasn't locked before (which we assume via fuzz), the call should succeed
        // and the contract balance should decrease by exactly 1 ether
        bool rule = success && (address(c).balance == balanceBefore - 1 ether);

        assertTrue(rule);
    }
}

