pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, bytes32 hash1, bytes32 hash2) public {
        vm.assume(sender != address(0));
        vm.deal(sender, 2 ether);

        // First call
        vm.prank(sender);
        c.lockInGuess{value: 1 ether}(hash1);

        // Second call
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", hash2));

        // After second call, the stored block should be 0 (due to lockInGuess resetting it)
        // In the reference, the second call reverts, so block remains non-zero; but we check the revert behavior via state
        // We can check via a settle call: if second call succeeded, block was reset to 0
        // Let's check by attempting to settle: if block == 0, settle reverts
        vm.prank(sender);
        (bool settled, ) = address(c).call(abi.encodeWithSignature("settle()"));

        // If the second call succeeded (mutant), then settle should revert because block is 0.
        // If the second call reverted (reference), settle should succeed.
        // So the rule: success == !settled
        assertTrue(success != settled);
    }
}

