pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint256 blockOffset) public {
        // Ensure blockOffset is positive so settle can be called after lockInGuess
        vm.assume(blockOffset > 0);
        // Ensure the caller has enough ether to lock in a guess
        vm.deal(address(this), 2 ether);

        // Lock in a guess
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance blocks
        for (uint256 i = 0; i < blockOffset; i++) {
            vm.roll(block.number + 1);
        }

        // Record balances before settle
        uint256 balanceBefore = address(this).balance;

        // Call settle; it may revert if the guess is incorrect (in reference) but we need to handle that
        // We use try/catch to capture whether it reverts
        try c.settle() {
            // If it didn't revert, we got paid: only true if guess matches
            // So assert that the guess actually matches the blockhash
            bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(block.number - blockOffset)));
            assertTrue(guessHash == expectedAnswer, "Settle should only transfer when guess matches answer");
        } catch {
            // If it reverted, that means the guess did NOT match
            // Assert that guess does NOT match the blockhash
            bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(block.number - blockOffset)));
            assertTrue(guessHash != expectedAnswer, "Settle should revert when guess does not match answer");
        }
    }
}

